    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نفصل السالبة عن الموجبة","math":"كل عدد سالب أصغر من كل عدد موجب"},{"quoi":"نرتّب السالبة","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">4</span></span> &lt; -<span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">4</span></span> &lt; -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span></span>"},{"quoi":"نرتّب الموجبة","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> &lt; <span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">5</span></span></span>"},{"quoi":"الترتيب الكامل","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">4</span></span> &lt; -<span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">4</span></span> &lt; -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> &lt; <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> &lt; <span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">5</span></span></span>"},{"quoi":"الطرفان","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">4</span></span> &lt; <span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">5</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نفصل السالبة عن الموجبة","math":"كل عدد سالب أصغر من كل عدد موجب"},{"quoi":"نرتّب السالبة","math":"لا يوجد عدد سالب"},{"quoi":"نرتّب الموجبة","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> &lt; <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> &lt; <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">4</span></span> &lt; <span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">4</span></span> &lt; <span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">5</span></span></span>"},{"quoi":"الترتيب الكامل","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> &lt; <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> &lt; <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">4</span></span> &lt; <span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">4</span></span> &lt; <span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">5</span></span></span>"},{"quoi":"الطرفان","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> &lt; <span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">5</span></span></span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نكتب البعد","math":"<span dir=\"ltr\" class=\"expr\">OP = |xP - 0| = |xP|</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">|xP| = 5</span>"},{"quoi":"القاعدة","math":"إذا كان <span dir=\"ltr\" class=\"expr\">|x| = k</span> و k > 0 فإنّ <span dir=\"ltr\" class=\"expr\">x = k</span> أو <span dir=\"ltr\" class=\"expr\">x = -k</span>"},{"quoi":"الحالتان","math":"<span dir=\"ltr\" class=\"expr\">xP = 5</span>  أو  <span dir=\"ltr\" class=\"expr\">xP = -5</span>"},{"quoi":"النتيجة","math":"للمسألة حلاّن متقابلان"}],
