    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"البعد بين نقطتين هو القيمة المطلقة للفرق بين فاصلتيهما"},{"quoi":"نكتب الفرق","math":"<span dir=\"ltr\" class=\"expr\">AM = |<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">5</span></span>|</span>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">5</span></span> = -<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span></span>"},{"quoi":"نأخذ القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|-<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span>| = <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">AM = <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"القاعدة","math":"إذا كانت P مناظرة M بالنسبة إلى O فإنّ O منتصف القطعة"},{"quoi":"نترجم","math":"<span dir=\"ltr\" class=\"expr\">OM = OP</span>"},{"quoi":"الفاصلتان متقابلتان","math":"<span dir=\"ltr\" class=\"expr\">xP = -xM</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">xP = -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">xP = -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"القاعدة","math":"البعد بين نقطتين هو القيمة المطلقة للفرق بين فاصلتيهما"},{"quoi":"نكتب الفرق","math":"<span dir=\"ltr\" class=\"expr\">MP = |-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span>|</span>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> = -5</span>"},{"quoi":"نأخذ القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|-5| = 5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">MP = 5</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"القاعدة","math":"البعد بين نقطتين هو القيمة المطلقة للفرق بين فاصلتيهما"},{"quoi":"نكتب الفرق","math":"<span dir=\"ltr\" class=\"expr\">NP = |-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - (-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>)|</span>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - (-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>) = -1</span>"},{"quoi":"نأخذ القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|-1| = 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">NP = 1</span>"}],
